package com.itemrespawntimer.staticspawnservice;

import com.itemrespawntimer.ItemRespawnTimerConfig;
import net.runelite.client.util.Text;

import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class BaseRespawnTicksReader {


    /**
     * The mapping itemId->baseRespawnTicks, to built by {@link #getMapItemIdToBaseRespawnTicks()}
     * key: The item id.
     * value: baseRespawnTicks, for this item.
     */
    Map<Integer,Integer> mapItemIdToBaseRespawnTicks = new HashMap<>();


    //region readResource
    private static final String resourceFilename = "BaseRespawnTicks.csv";


    private String readResource(){
        try (InputStream in = ItemRespawnTimerConfig.class.getClassLoader().getResourceAsStream(resourceFilename)) {
            if (in == null) {
                throw new IOException("Resource not found: " + resourceFilename);
            }
            return new String(in.readAllBytes(), StandardCharsets.UTF_8);
        } catch(IOException e){
            return "";
        }
    }
    //endregion


    /**
     * Get the parsed records from the resource file, as a map itemId->baseRespawnTicks.
     * @return The mapping defined by the records.
     */
    public Map<Integer,Integer> getMapItemIdToBaseRespawnTicks(){
        readResource().lines()
                .forEach(this::parseCsvLine);

        return mapItemIdToBaseRespawnTicks;
    }


    /**
     * Parse a line of itemId->baseRespawnTicks data,
     *      and put the result in {@link #mapItemIdToBaseRespawnTicks}.
     * If the line doesn't parse as itemId->baseRespawnTicks data, the line will be skipped.
     * The rest of the line after a `#` character is ignored as a comment in the data.
     *
     * @param baseRespawnTicksCsvLine The single line of CSV data to parse.
     */
    @SuppressWarnings("UnnecessaryReturnStatement")
    private void parseCsvLine(String baseRespawnTicksCsvLine){
        String lineWithoutComment = baseRespawnTicksCsvLine.split("#",2)[0];

        /*
         * `lineData` is the record data:
         * [0]:itemId,[1]:baseRespawnTicks
         */
        List<String> lineData = Text.fromCSV(lineWithoutComment);

        try {

            int itemId = Integer.parseInt(lineData.get(0));
            int baseRespawnTicks = Integer.parseInt(lineData.get(1));

            mapItemIdToBaseRespawnTicks.put(itemId,baseRespawnTicks);

        }
        catch (
                IndexOutOfBoundsException // skip this line if line doesn't have enough data cells
                | NumberFormatException // skip this line if cell data doesn't parse
                        e
        ) {
            return;
        }

    }
    //endregion

}

package com.itemrespawntimer.staticspawnservice;

import java.util.*;
import javax.inject.Singleton;

import com.itemrespawntimer.timermodel.RespawnTimer;
import lombok.extern.slf4j.Slf4j;

import net.runelite.api.coords.WorldPoint;

@Slf4j
@Singleton
public class StaticSpawnService
{

    //region ashes spawns
    private static final List<WorldPoint> ashesSpawnPoints = List.of(
            new WorldPoint(1497,3173,0), // [[Bandit (Varlamore)|Bandit]]s' camp north-east of [[Ralos' Rise]]
            new WorldPoint(3752,9780,0), // [[Sisterhood Sanctuary]]
            new WorldPoint(1834,6187,0) // [[Realm of Memories]]
    );


    private static final int ashesItemId = 592;


    /**
     * Check whether a spawn is probably ashes from burned out fires.
     * @param wp The world point to check.
     * @param itemId The itemId to check
     * @return Result of the test.
     */
    private static boolean isAshesNotFromSelectSpawnPoints(WorldPoint wp, int itemId) {
        return itemId == ashesItemId // is an ashes item
                && ashesSpawnPoints.stream().filter(sp -> sp.equals(wp)).findAny().isEmpty(); // is not at an ashes spawn point
    }
    //endregion


    /**
     * Get a static spawn information using the baseRespawnTicks data. or empty optional if no baseRespawnTicks for this item id.
     * @param wp The world point to set.
     * @param itemId The itemId to look up and to set.
     * @param quantity The quantity to set.
     * @return The static spawn info or an empty optional.
     */
    public Optional<StaticSpawn> getTrackedSpawn(WorldPoint wp, int itemId, int quantity){
        if( isAshesNotFromSelectSpawnPoints(wp, itemId) ){ return Optional.empty(); }// skip ashes that are from fires burning out
        // POH served food is also OWNERSHIP_NONE, so if any of those items had an item spawn, a check would be needed here to exclude the POH. But we're ok for now as none of them have any spawns so they're not in the baseRespawnTicks data.

        return Optional.ofNullable(mapItemIdToBaseRespawnTicks.get(itemId))
                .map(baseRespawnTicks ->
                        new StaticSpawn(
                                wp,
                                baseRespawnTicks,
                                itemId,
                                quantity)
                );
    }


    /**
     * key: The item id.
     * value: baseRespawnTicks, for this item.
     */
    Map<Integer, Integer> mapItemIdToBaseRespawnTicks = new HashMap<>();


    public void startUp(){
        mapItemIdToBaseRespawnTicks = (new BaseRespawnTicksReader())
                .getMapItemIdToBaseRespawnTicks();
    }


    //region isSpawnLocationWithinViewDistance
    /**
     * Check if the spawn location is within the range that the player can see if the item respawns.
     * @param spawnPoint The spawn location
     * @param playerPoint The current player position.
     * @return The result of the check
     */
    public static boolean isSpawnLocationWithinViewDistance(WorldPoint spawnPoint, WorldPoint playerPoint){
        //can see the current zone plus a range of 3 zones, a 7zones*7zones area. (a zone is 8tiles*8tiles)
        return (playerPoint.getPlane() == spawnPoint.getPlane())
                && Math.abs(playerPoint.getX()/8 - spawnPoint.getX()/8) <= 3
                && Math.abs(playerPoint.getY()/8 - spawnPoint.getY()/8) <= 3;
    }


    /**
     * Check if the spawn location is within the range that the player can see if the item respawns.
     * @param timer The timer to check the spawn location of.
     * @param playerPoint The current player position.
     * @return The result of the check
     */
    public static boolean isSpawnLocationWithinViewDistance(RespawnTimer timer, WorldPoint playerPoint){
        return isSpawnLocationWithinViewDistance(timer.getWorldPoint(), playerPoint);
    }
    //endregion

}

package com.itemrespawntimer.staticspawnservice;

import lombok.Value;
import net.runelite.api.coords.WorldPoint;


@Value
public class StaticSpawn
{
    /**
     * The location in the world where this spawns.
     */
    WorldPoint worldPoint;

    /**
     * The number of ticks used as the base respawn rate.
     * More populated words respawn faster.
     */
    int baseRespawnTicks;

    /**
     * The numerical id of the item. Or -1 to track any item.
     */
    int itemId;

    /**
     * The quantity of the stack, used for finding total stack value.
     */
    int quantity;

}

package com.itemrespawntimer.panel;

import javax.swing.*;
import javax.inject.Inject;
import java.time.Instant;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.Set;

import com.itemrespawntimer.timermodel.ActiveTimers;
import com.itemrespawntimer.timermodel.RespawnTimer;
import lombok.Setter;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.PluginPanel;


public class ItemRespawnTimerPanel extends PluginPanel {

    private final java.util.List<ItemRespawnTimeablePanel> spawnPanels;

    private final Set<RespawnTimer> shownTimers;

    //protected JLabel label;
    protected JTextArea textArea;

    @Inject
    public ItemRespawnTimerPanel()
    {
        /*
        todo: make tiles with buttons for each timer
         */
        //setLayout(new BorderLayout());
        textArea = new JTextArea("Hello RuneLite!");
        //add(textArea, BorderLayout.NORTH);// todo remove text mode

        spawnPanels = new ArrayList<>();
        shownTimers = new HashSet<>();

    }



    @Inject
    private ActiveTimers activeTimers;

    @Setter
    private int currentWorldId;

    @Inject
    private ItemManager itemManager;


    public void updateSidePanel()
    {
        long nowMillis = Instant.now().toEpochMilli();

        //remove deleted timers
        for  (ItemRespawnTimeablePanel panel : spawnPanels) {
            RespawnTimer timer = panel.getTimeable();
            if (timer.isDeleted()){
                spawnPanels.remove(panel);
                shownTimers.remove(timer);
                remove(panel);
                revalidate();
            }
        }

        //add new timer panels
        for(int i=0; i<activeTimers.getActiveTimers().size(); ++i){
            RespawnTimer t = activeTimers.getActiveTimers().get(i);

            if (shownTimers.contains(t)){ continue; }

            ItemRespawnTimeablePanel panel = new ItemRespawnTimeablePanel(t, itemManager);

            add(panel,i);
            spawnPanels.add(panel);
            shownTimers.add(t);
        }

        //update progress
        for (ItemRespawnTimeablePanel panel : spawnPanels){
            panel.update(currentWorldId, nowMillis);

        }
    }
}

package com.itemrespawntimer.panel;

import com.itemrespawntimer.net.runelite.client.plugins.timetracking.TimeablePanel;

import com.itemrespawntimer.timermodel.RespawnTimer;
import net.runelite.client.game.ItemManager;

import java.awt.*;
import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;


class ItemRespawnTimeablePanel
extends TimeablePanel<RespawnTimer>
{

  String estimateAtTimePart;
  String estimateWorldPart;
  boolean isStaleColorsSet = false;

  ItemRespawnTimeablePanel(RespawnTimer timer, ItemManager itemManager)
  {
    super(
            timer,
            itemManager.getItemComposition(timer.getSpawn().getItemId()).getName(), // item name
            timer.getTotalMillis()
    );


    itemManager.getImage(timer.getSpawn().getItemId()).addTo(getIcon());

    String itemName = getText().getText();
    getIcon().setToolTipText(itemName);

    getProgress().setVisible(true);
    remove(getNotifyButton());
    getProgress().setForeground(Color.GREEN);
    getProgress().setBackground(Color.DARK_GRAY);

    prepareEstimateParts();
    update(timer.getWorldId(),timer.getStart());

  }

  public void update(int currentWorldId, long nowMillis)
  {
    updateEstimateMessage(currentWorldId);
    updateProgress(nowMillis);
  }

  public void updateEstimateMessage(int currentWorldId)
  {
    RespawnTimer timer = getTimeable();
    String atTimePart = (timer.isExpired()) ? "" : estimateAtTimePart;
    String worldPart = (timer.getWorldId() == currentWorldId) ? "" : estimateWorldPart;

    getEstimate().setText(String.format("Done%s%s", atTimePart, worldPart));
  }


  private static final DateTimeFormatter formatterMinutesAndSeconds = DateTimeFormatter.ofPattern("mm:ss");

  private void prepareEstimateParts()
  {
    RespawnTimer timer = getTimeable();

    estimateWorldPart = String.format(" in W%s", timer.getWorldId());

    String doneAtMinutesAndSeconds = Instant.ofEpochMilli(timer.getRespawnAt()).atZone(ZoneId.of("UTC")).format(formatterMinutesAndSeconds);
    estimateAtTimePart = String.format(" at %s", doneAtMinutesAndSeconds);
  }


  public void updateProgress(long nowMillis)
  {
    RespawnTimer timer = getTimeable();
    int progress;
    if (timer.isExpired()){
      if (!isStaleColorsSet) { setStaleColors(); }
      progress = (int) (nowMillis - timer.getRespawnAt());
    } 
    else
    {
      progress = (int) (nowMillis - timer.getStart());
    }

    getProgress().setValue(progress);
  }

  private void setStaleColors()
  {
    isStaleColorsSet = true;
    getProgress().setForeground(Color.DARK_GRAY);
    getProgress().setBackground(Color.GREEN);
  }
}

