package com.itemrespawntimer.timermodel;

import com.itemrespawntimer.staticspawnservice.StaticSpawn;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.coords.WorldPoint;

import java.time.Instant;

@Slf4j
public class RespawnTimer
{

    //region final values
    /**
     * item and location information
     */
    @Getter
    private final StaticSpawn spawn;


    /**
     * the world that the item will respawn in
     */
    @Getter
    private final int worldId;


    /**
     * when the timer started, as a millisecond timestamp
     */
    @Getter
    private final long start;


    /**
     * when the item will respawn, as a millisecond timestamp
     */
    @Getter
    private final long respawnAt;


    /**
     * the time after twice the respawn delay, as a millisecond timestamp
     */
    @Getter
    private final long twiceRespawnTime;


    /**
     * the total time that the timer is counting out of
     */
    @Getter
    private final int totalSeconds;


    /**
     * the total time that the timer is counting out of
     */
    @Getter
    private final int totalMillis;
    //endregion


    //region deleted
    /**
     * Whether the timer is to be discarded
     */
    @Getter
    private boolean deleted;


    /**
     * The timer is to be discarded.
     */
    public void delete(){
        deleted = true;
    }
    //endregion


    public RespawnTimer(
            StaticSpawn spawn,
            int worldId,
            int worldPopulation
    )
    {
        this.spawn = spawn;
        this.worldId = worldId;
        this.start = Instant.now().toEpochMilli();

        int respawnDelayTicks = (int)Math.floor(this.spawn.getBaseRespawnTicks() * ((4000D-worldPopulation)/4000));
        this.respawnAt =        start + (    respawnDelayTicks * 600L);
        this.twiceRespawnTime = start + (2 * respawnDelayTicks * 600L);

        int respawnDelaySeconds = (int)(respawnDelayTicks*0.6);
        this.totalSeconds = Math.max(respawnDelaySeconds, 1); // fallback if somehow respawnDelaySeconds is 0, to avoid any divide by zeros


        int respawnDelayMillis = (respawnDelayTicks*600);
        this.totalMillis = Math.max(respawnDelayMillis, 1); // fallback if somehow respawnDelayMillis is 0, to avoid any divide by zeros


    }


    //region getters
    /**
     * the location in the world where the spawn is
     */
    public WorldPoint getWorldPoint(){
        return spawn.getWorldPoint();
    }

    /**
     * Check if current time exceeds {@link #}respawnAt}.
     * @return Whether time T-0 has passed.
     */
    public boolean isExpired(){
        long nowMillis = Instant.now().toEpochMilli();
        return nowMillis > respawnAt;
    }


    /**
     * The proportion of progress out of totalSeconds, for drawing the dial.
     * @return number from 0.0 to 1.0
     */
    public double getProgress()
    {
        long nowMillis = Instant.now().toEpochMilli();
        long elapsedMillis = nowMillis - start;
        double progress = elapsedMillis / (totalSeconds * 1000.0);

        return Math.min(Math.max( // clamped progress between 0.0 and 1.0. Math.clamp is not available for java 11
                progress,
                0.0), 1.0);
    }
    //endregion

}

package com.itemrespawntimer.timermodel;

import com.itemrespawntimer.ItemRespawnTimerPlugin;
import com.itemrespawntimer.staticspawnservice.StaticSpawnService;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Tile;
import net.runelite.api.TileItem;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ItemDespawned;
import net.runelite.api.events.ItemSpawned;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.time.Instant;
import java.util.*;

@Slf4j
@Singleton
public class ActiveTimers {
    //region head
    @Inject
    private Client client;


    @Inject
    private ItemRespawnTimerPlugin plugin;


    @Inject
    private StaticSpawnService staticSpawnService;

    @Inject
    private DespawnEventVerificationService despawnEventVerificationService;
    //endregion


    /**
     * The collection of active 'RespawnTimer's.
     * Ordered by respawn time (ties broken by worldId then by worldPoint).
     * No more than 1 timer for the same worldId and worldPoint.
     */
    @Getter
    public final LinkedList<RespawnTimer> activeTimers = new LinkedList<>();


    //region add(RespawnTimer newTimer)
    /**
     * Add a respawn timer to the list.
     * @param newTimer The timer to add.
     */
    public void add(RespawnTimer newTimer){
        removeIfSameWorldAndLocationAs(newTimer);
        activeTimers.add(insertionIndex(newTimer), newTimer);
    }


    /**
     * Remove any timers at the same location in the same world, to ensure there's only ever one per location.
     * @param newTimer The timer about to be added to the list.
     */
    private void removeIfSameWorldAndLocationAs(RespawnTimer newTimer)
    {
        activeTimers.removeIf(t-> (
                (newTimer.getWorldId()==t.getWorldId())
                        && (newTimer.getWorldPoint().equals(t.getWorldPoint()))
        ));
    }


    /**
     * Ordering for the timers list to be maintained in.
     */
    private final Comparator<RespawnTimer> ordering =  Comparator
            .comparingLong(RespawnTimer::getRespawnAt)
            .thenComparingInt(RespawnTimer::getWorldId)
            .thenComparingInt(t->t.getWorldPoint().getPlane())
            .thenComparingInt(t->t.getWorldPoint().getY())
            .thenComparingInt(t->t.getWorldPoint().getX());


    /**
     * Find the index to insert at to maintain the order of the timers list.
     * @param newTimer The timer about to be added to the list.
     * @return The insertion index.
     */
    private int insertionIndex(RespawnTimer newTimer){
        int insertionIndex = 0;
        for (RespawnTimer t : activeTimers){
            // want first index where newTimer is sorted before existing element
            if (ordering.compare(newTimer, t) < 0) {
                break;
            }
            ++insertionIndex;
        }
        return insertionIndex;
    }
    //endregion


    //region clear
    public void clear(){
        activeTimers.clear();
    }


    private void clearDeletedTimers(){
        activeTimers.removeIf(RespawnTimer::isDeleted);
    }
    //endregion

    public void onGameTick(){//todo can i make this subscribe?
        removeTick();
    }

    /**
     * Delete matching timer when observe an item spawn.
     * @param event the item spawned
     */
    public void onItemSpawned(ItemSpawned event){ //todo can i make this subscribed
        Tile tile = event.getTile();
        TileItem item = event.getItem();
        if (tile == null || item == null) {
            return;
        }

        if (item.getOwnership() != TileItem.OWNERSHIP_NONE){
            return; // only react to items that were naturally spawned
        }

        WorldPoint spawnedWorldPoint = tile.getWorldLocation();
        int spawnedItemId = item.getId();
        int currentWorldId = client.getWorld();

        deleteMatchingTimer(spawnedWorldPoint,spawnedItemId,currentWorldId);
    }

    private void deleteMatchingTimer(
            WorldPoint spawnedWorldPoint,
            int spawnedItemId,
            int currentWorldId
    ){
        activeTimers.stream()
                .filter(timer -> (
                        timer.getWorldPoint().equals(spawnedWorldPoint)
                                && timer.getSpawn().getItemId() == spawnedItemId
                                && timer.getWorldId() == currentWorldId
                ))
                .forEach(RespawnTimer::delete);
    }




    /**
     * Add a timer for picked up item.
     * @param event the item despawned
     */
    public void onItemDespawned(ItemDespawned event){//todo can i make this subscribed
        Tile tile = event.getTile();
        TileItem item = event.getItem();
        if (tile == null || item == null)
        {
            return;
        }

        if (item.getOwnership() != TileItem.OWNERSHIP_NONE){
            return; // only react to items that were naturally spawned
        }

        if (despawnEventVerificationService.despawnEventMaybeFromReenteringAnArea(event)){
            return;// filter out delayed despawn events from returning to a location but not directly witnessing the item being taken
        }

        WorldPoint wp = tile.getWorldLocation();

        staticSpawnService.getTrackedSpawn(wp, item.getId(), item.getQuantity())
                .ifPresent(spawn -> {
                    int worldId = client.getWorld();
                    int worldPopulation = plugin.getCurrentWorldPopulation();

                    RespawnTimer timer = new RespawnTimer(spawn,worldId,worldPopulation);
                    add(timer);
                });
    }


    //region removeTick
    /**
     * Sets the deleted state for timers matching the config auto-removal conditions. Then calls {@link #clearDeletedTimers}.
     * @see RespawnTimer#delete
     */
    private void removeTick(){
        activeTimers.stream()
                .filter(timer -> toAutomaticallyDelete(
                        timer,
                        Instant.now().toEpochMilli(),
                        client.getWorld(),
                        client.getLocalPlayer().getWorldLocation()
                ))
                .forEach(RespawnTimer::delete);

        clearDeletedTimers();
    }

    private boolean toAutomaticallyDelete(
            RespawnTimer timer,
            long nowMillis,
            int currentWorldId,
            WorldPoint playerPoint
    ){
        boolean expiredAndCanSeeLocation = (
                timer.isExpired()
                && (timer.getWorldId()==currentWorldId)
                && StaticSpawnService.isSpawnLocationWithinViewDistance(timer,playerPoint)
        );

        boolean twiceExpiredTime = (nowMillis >= timer.getTwiceRespawnTime());

        return expiredAndCanSeeLocation || twiceExpiredTime;
    }
    //endregion

}

package com.itemrespawntimer.timermodel;

import com.itemrespawntimer.staticspawnservice.StaticSpawnService;
import net.runelite.api.Client;
import net.runelite.api.Tile;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ItemDespawned;

import javax.inject.Inject;
import javax.inject.Singleton;

/**
 * This service is for verifying that an item despawn event is actually from an item being taken.
 * This is needed because you also get an item despawn event from the following situation:
 * When you leave the view distance from an item and then re-enter the view distance, you will get an item despawn event when you re-enter regardless of whether the item is still there or not.
 */
@Singleton
public class DespawnEventVerificationService {


    @Inject
    private Client client;


    /**
     * The player location in [0] this tick and [1] the previous tick, so we can detect whether an onItemDespawn is actually from re-entering the area without directly observing it being taken.
     * Recording both to ensure we have the previous tick location:
     *  - if updating fires early in the tick [0] would have this tick location.
     *  - if updating fires late in the tick [1] would have location of 2 ticks ago.
     */
    private final WorldPoint[] previousTickPlayerLocation = new WorldPoint[2];


    /**
     * Update values of {@link #previousTickPlayerLocation}.
     */
    public void onGameTick()// todo can i make this subscribed?
    {

        previousTickPlayerLocation[1] = previousTickPlayerLocation[0];
        previousTickPlayerLocation[0] = client.getLocalPlayer().getWorldLocation();
    }


    /**
     * Check if the spawn location was outside the view distance in this tick or the previous tick.
     * @param event The event with the spawn location to check.
     * @return Result of the check
     * @throws NullPointerException if event doesn't have an associated tile
     */
    public boolean despawnEventMaybeFromReenteringAnArea(ItemDespawned event) throws NullPointerException
    {
        Tile tile = event.getTile();
        WorldPoint spawnPoint = tile.getWorldLocation();
        return spawnLocationMayHaveEnteredViewDistanceThisTick(spawnPoint);
    }


    /**
     * Check if the spawn location was outside the view distance in this tick or the previous tick.
     * @param spawnPoint The spawn location to check.
     * @return Result of the check
     */
    public boolean spawnLocationMayHaveEnteredViewDistanceThisTick(WorldPoint spawnPoint){
        return(
                !StaticSpawnService.isSpawnLocationWithinViewDistance(spawnPoint,previousTickPlayerLocation[0])
                        || !StaticSpawnService.isSpawnLocationWithinViewDistance(spawnPoint,previousTickPlayerLocation[1])
        );
    }

}

package com.itemrespawntimer;

