import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

import java.awt.image.BufferedImage;
import java.time.temporal.ChronoUnit;

import net.runelite.client.task.Schedule;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.api.events.ItemDespawned;
import net.runelite.client.util.ImageUtil;
import net.runelite.http.api.worlds.WorldResult;


@Slf4j
@PluginDescriptor(
	name = "Item Respawn Timer",
	description = "Show timers for respawning items",
	tags = {"spawn","collecting","ironman","money making","money","making","telegrabbing","telekinetic grab","telekinetic","grab","herblore","secondary"}
)
public class ItemRespawnTimerPlugin extends Plugin
{
	//region head
	@Inject
	private Client client;


	@SuppressWarnings("unused")
    @Inject
	private ItemRespawnTimerConfig config;


	@Inject
	private OverlayManager overlayManager;


	@Inject
	private ClientToolbar clientToolbar;


	@Inject
	private ItemRespawnTimerOverlay overlay;


	@Inject
	private StaticSpawnService staticSpawnService;


	@Inject
	private ActiveTimers activeTimers;


	@Inject
	private DespawnEventVerificationService despawnEventVerificationService;


	@Inject
	private WorldService worldService;
	//endregion


	private ItemRespawnTimerPanel panel;
	private NavigationButton navButton;


	//region set up
    @SuppressWarnings("RedundantThrows")
    @Override
	protected void startUp() throws Exception
	{
		log.debug("Item Respawn Timer plugin started!");
		overlayManager.add(overlay);

		staticSpawnService.startUp();

		startupSidePanel();
	}

	private void startupSidePanel(){
		panel = injector.getInstance(ItemRespawnTimerPanel.class);
		final BufferedImage icon = ImageUtil.loadImageResource(ItemRespawnTimerPlugin.class, "/icon.png");

		navButton = NavigationButton.builder()
			.tooltip("Item Respawns")
			.panel(panel)
			.icon(icon)
			.build();

		clientToolbar.addNavigation(navButton);
	}


	@SuppressWarnings("RedundantThrows")
    @Override
	protected void shutDown() throws Exception
	{
		log.debug("Item Respawn Timer plugin  stopped!");
		overlayManager.remove(overlay);
		activeTimers.clear();//todo do i need to clear this?
		//todo do i need a shutdown for staticSpawnService?
		clientToolbar.removeNavigation(navButton);
	}


	@SuppressWarnings("unused")
    @Provides
	ItemRespawnTimerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ItemRespawnTimerConfig.class);
	}
	//endregion


	@SuppressWarnings("unused")
    @Subscribe
	public void onItemSpawned(ItemSpawned event)
	{
		activeTimers.onItemSpawned(event);
		overlay.onItemSpawned(event);
	}

	@SuppressWarnings("unused")
    @Subscribe
	public void onItemDespawned(ItemDespawned event)
	{
		activeTimers.onItemDespawned(event);
	}


	@SuppressWarnings("unused")
    @Subscribe
	public void onGameTick(GameTick event) {
		despawnEventVerificationService.onGameTick();
		activeTimers.onGameTick();
		panel.setCurrentWorldId(client.getWorld());//todo move to the onGameStateChanged event
	}


	@SuppressWarnings("unused")
    @Schedule(
			period = 1,
			unit = ChronoUnit.SECONDS
	)
	public void updateSidePanel()
	{
		panel.updateSidePanel();
	}


	public int getCurrentWorldPopulation(){
		int currentWorldId = client.getWorld();
		WorldResult worlds = worldService.getWorlds();

		if (worlds != null)
		{
			net.runelite.http.api.worlds.World world = worlds.findWorld(currentWorldId);
			if (world != null)
			{
				return world.getPlayers();
			}
		}
		return 0;
	}

}

package com.itemrespawntimer;

import java.awt.*;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;

import com.itemrespawntimer.timermodel.ActiveTimers;
import net.runelite.api.*;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ItemSpawned;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.ProgressPieComponent;

public class ItemRespawnTimerOverlay extends Overlay
{
    private final Client client;
    @SuppressWarnings({"FieldCanBeLocal", "unused"})
    private final ItemRespawnTimerPlugin plugin;
    private final ItemRespawnTimerConfig config;

    @Inject
    private ActiveTimers activeTimers;


    @Inject
    public ItemRespawnTimerOverlay(Client client, ItemRespawnTimerPlugin plugin, ItemRespawnTimerConfig config)
    {
        this.client = client;
        this.plugin = plugin;
        this.config = config;

        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }


    @Override
    public Dimension render(Graphics2D graphics)
    {
        int currentWorldId = client.getWorld();
        if (!config.overlayEnabled())
        {
            return null;
        }

        activeTimers.getActiveTimers().stream()
                .filter(timer -> timer.getWorldId() == currentWorldId)
                .filter(timer -> !timer.isExpired())
                .forEach(timer -> {
                    LocalPoint loc = LocalPoint.fromWorld(client, timer.getWorldPoint());
                    if (loc == null)
                    {
                        return;
                    }

                    double percent = timer.getProgress(); // 0.0 -> 1.0

                    int plane = client.getTopLevelWorldView().getPlane();
                    int heightOffset = itemHeightOffset.getOrDefault(timer.getWorldPoint(), 0);

                    Point point = Perspective.localToCanvas(client, loc, plane, heightOffset);
                    if (point == null)
                    {
                        return;
                    }

                    Color pieFillColor = Color.YELLOW;
                    Color pieBorderColor = Color.ORANGE;

                    ProgressPieComponent ppc = new ProgressPieComponent();
                    ppc.setBorderColor(pieBorderColor);
                    ppc.setFill(pieFillColor);
                    ppc.setPosition(point);
                    ppc.setProgress(percent);
                    ppc.render(graphics);
                });

        return null;
    }

    /**
     * The height offset for the item layer at a given location, for the timer to be displayed on top of tables.
     * Left unset for 0s, use getOrDefault(wp, 0).
     */
    private final Map<WorldPoint, Integer> itemHeightOffset = new HashMap<>();

    /**
     * Add the height data, to ensure {@link #itemHeightOffset} has the height data for any item spawn seen.
     * @param event the item spawned
     */
    public void onItemSpawned(ItemSpawned event){
        Tile tile = event.getTile();
        TileItem item = event.getItem();
        if (tile == null || item == null)
        {
            return;
        }

        if (item.getOwnership() != TileItem.OWNERSHIP_NONE){
            return; // only react to items that were naturally spawned
        }

        ItemLayer itemLayer = tile.getItemLayer();
        if (itemLayer == null)
        {
            return;
        }

        int heightOffset = itemLayer.getHeight();
        if (heightOffset == 0)
        {
            return; // don't record 0s. Can assume 0 from absent. And to prevent ashes from burned out fires bloating the size of the map.
        }

        WorldPoint wp = tile.getWorldLocation();

        itemHeightOffset.putIfAbsent(wp, heightOffset);
    }
}

